import java.util.ArrayList;
import java.util.List;

class Variance {
    static void demo() {
        List<String> names = new ArrayList<>();
        // List<Object> objects = names;       // error: invariant
        List<? extends Object> view = names;   // OK: a read-only view, written at the use site
        Object first = view.isEmpty() ? null : view.get(0);

        String[] varieties = { "Gala" };
        Object[] objects = varieties;          // OK: arrays are covariant
        objects[0] = 42;                       // compiles, throws ArrayStoreException
    }
}

